<article class="panel document-history">
 <div class="panel-head"><div><span class="panel-kicker">HISTORIAL CENTRAL</span><h2>Resultados de la consulta</h2><p><?=$total?> <?=$total===1?'documento encontrado':'documentos encontrados'?> · mostrando <?=$firstResult?>–<?=$lastResult?></p></div><label class="page-size"><span>Mostrar</span><select class="history-page-size" aria-label="Resultados por página"><?php foreach([25,50,100,200] as $size):?><option value="<?=$size?>" <?=$perPage===$size?'selected':''?>><?=$size?></option><?php endforeach;?></select><span>por página</span></label></div>
 <div class="table-scroll"><table><thead><tr><th>Documento</th><th>Empresa y local</th><th>Cliente</th><th>Emisión</th><th>Total</th><th>Estado</th></tr></thead><tbody>
 <?php if(!$rows):?><tr><td colspan="6" class="empty"><div class="filter-empty"><i class="fas fa-search"></i><strong>No encontramos comprobantes</strong><span>Amplía las fechas o quita alguno de los filtros.</span></div></td></tr><?php endif;?>
 <?php foreach($rows as $row):$companyName=$row['em_nombre_comercial']?:$row['em_razon_social'];?><tr><td><strong><?=$e($row['serie'].'-'.str_pad((string)$row['correlativo'],8,'0',STR_PAD_LEFT))?></strong><small><?=$e(PanelCentral::tipoDocumento((string)$row['tipo_doc']))?></small></td><td><strong><?=$e($companyName)?></strong><small><i class="fas fa-map-marker-alt"></i> <?=$e($row['loc_nombre']?:'Local no identificado')?></small></td><td><?=$e($row['cliente_razon_social']?:'Cliente general')?><small><?=$e($row['cliente_num_doc']?:'Sin documento')?></small></td><td><?=$e(date('d/m/Y',strtotime((string)$row['fecha_emision'])))?></td><td><strong>S/ <?=number_format((float)$row['total'],2)?></strong></td><td><span class="badge <?=$e($row['estado'])?>"><?=$e(ucfirst((string)$row['estado']))?></span></td></tr><?php endforeach;?>
 </tbody></table></div>
 <?php if($totalPages>1):?><footer class="history-pagination"><p>Mostrando <strong><?=$firstResult?>–<?=$lastResult?></strong> de <strong><?=$total?></strong> comprobantes</p><nav aria-label="Paginación de comprobantes"><a class="page-arrow <?=$currentPage<=1?'disabled':''?>" href="<?=$currentPage>1?$e($pageUrl($currentPage-1)):'#'?>" aria-label="Página anterior"><i class="fas fa-chevron-left"></i></a><?php if($pageStart>1):?><a href="<?=$e($pageUrl(1))?>">1</a><?php if($pageStart>2):?><span>…</span><?php endif;?><?php endif;?><?php for($number=$pageStart;$number<=$pageEnd;$number++):?><a class="<?=$number===$currentPage?'active':''?>" href="<?=$e($pageUrl($number))?>" <?=$number===$currentPage?'aria-current="page"':''?>><?=$number?></a><?php endfor;?><?php if($pageEnd<$totalPages):?><?php if($pageEnd<$totalPages-1):?><span>…</span><?php endif;?><a href="<?=$e($pageUrl($totalPages))?>"><?=$totalPages?></a><?php endif;?><a class="page-arrow <?=$currentPage>=$totalPages?'disabled':''?>" href="<?=$currentPage<$totalPages?$e($pageUrl($currentPage+1)):'#'?>" aria-label="Página siguiente"><i class="fas fa-chevron-right"></i></a></nav></footer><?php endif;?>
</article>
